const a = finderAnswers.value;
const smallTeam = ["1\u201310", "11\u201350"].includes(a.company_size);
const smallBudget = ["Under \u20b92L", "\u20b92L\u2013\u20b910L"].includes(a.budget);
const immediate = a.timeline === "Immediately";
const standard = ["New ERP Implementation", "Replace Existing ERP"].includes(a.looking_for);
const qualifies = smallTeam && smallBudget && immediate && standard;
finderOutcome.value = qualifies ? 'starter' : 'matches';
finderStep.value = 5;
call('connect.api.save_customer_requirement', {
  company_name: a.company_name, country: a.country, industry: a.industry,
  apps: JSON.stringify(a.apps || []),
  looking_for: a.looking_for, company_size: a.company_size,
  current_situation: a.current_situation, timeline: a.timeline,
  delivery_preference: a.delivery_preference, budget: a.budget,
  special_requirements: JSON.stringify(a.requirements || []), outcome: qualifies ? 'Starter Pack' : 'Matches',
}).then(() => {
  if (myRequirement && myRequirement.reload) { myRequirement.reload(); }
  toast({ title: 'Saved', text: 'Your requirements have been saved.', icon: 'check' });
}).catch(() => {
  toast({ title: 'Not saved', text: 'Log in to save your requirements for later.', icon: 'alert-circle' });
});

update:modelValue.script:
const cur = settingsApps.value || [];
const val = dataItem;
const next = cur.includes(val) ? cur.filter(v => v !== val) : [...cur, val];
settingsApps.value = next;

const cur = settingsSpecialRequirements.value || [];
const val = dataItem;
const next = cur.includes(val) ? cur.filter(v => v !== val) : [...cur, val];
settingsSpecialRequirements.value = next;

click.script:
settingsSaving.value = true;
call('connect.api.save_customer_requirement', {
  company_name: settingsCompanyName.value,
  country: settingsCountry.value,
  industry: settingsIndustry.value,
  apps: settingsApps.value,
  looking_for: settingsLookingFor.value,
  company_size: settingsCompanySize.value,
  current_situation: settingsCurrentSituation.value,
  timeline: settingsTimeline.value,
  delivery_preference: settingsDeliveryPreference.value,
  budget: settingsBudget.value,
  special_requirements: JSON.stringify(settingsSpecialRequirements.value || []),
}).then(() => {
  settingsSaving.value = false;
  settingsOpen.value = false;
  if (myRequirement && myRequirement.reload) { myRequirement.reload(); }
  toast({ title: 'Saved', text: 'Your requirements have been saved.', icon: 'check' });
}).catch((err) => {
  settingsSaving.value = false;
  toast({ title: 'Could not save', text: (err && err.message) || 'Please try again', icon: 'x' });
});

